#pragma once

static const char KLIMA_WEB_UI[] =
"<!doctype html><html lang='en'><head><meta charset='utf-8'>"
"<meta name='viewport' content='width=device-width,initial-scale=1'>"
"<title>Klima WiFi</title><link rel='icon' href='data:,'><style>"
":root{color-scheme:dark;--bg:#081012;--panel:#111b1e;--line:#26383d;--ink:#eef8f5;--muted:#94aaa6;--accent:#5ee0b5;--warn:#ffca68}"
"*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 15% 0,#16322f 0,transparent 36rem),var(--bg);color:var(--ink);font:15px/1.5 system-ui,sans-serif}"
"main{width:min(1180px,calc(100% - 28px));margin:auto;padding:30px 0 48px}header{display:flex;justify-content:space-between;gap:20px;align-items:end;margin-bottom:20px}"
"h1{font-size:clamp(30px,6vw,58px);line-height:.95;margin:0;letter-spacing:-.055em}h2{font-size:17px;margin:0 0 12px}header p{margin:8px 0 0;color:var(--muted)}"
".dot{display:inline-block;width:9px;height:9px;border-radius:50%;background:var(--warn);margin-right:7px}.dot.ok{background:var(--accent);box-shadow:0 0 16px #5ee0b588}"
".layout{display:grid;grid-template-columns:minmax(0,1fr) 380px;gap:18px}.stack{display:grid;gap:16px;align-content:start}.panel{background:#11191cdd;border:1px solid var(--line);border-radius:18px;padding:18px;box-shadow:0 18px 50px #0005}"
".toolbar,.row{display:flex;flex-wrap:wrap;gap:8px;align-items:center}.toolbar{margin-bottom:12px}.toolbar strong{margin-right:auto}.pill{border:1px solid var(--line);border-radius:999px;padding:6px 10px;color:var(--muted)}"
"button{border:1px solid #37635a;background:#18352f;color:var(--ink);border-radius:10px;padding:9px 13px;font:inherit;cursor:pointer}button:disabled{opacity:.45;cursor:not-allowed}"
"pre{height:70vh;min-height:390px;margin:0;padding:14px;background:#070b0d;border:1px solid #1b292e;border-radius:12px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;color:#bcefdc;font:12px/1.45 ui-monospace,monospace}"
".metric{display:grid;grid-template-columns:1fr auto;gap:8px;padding:8px 0;border-bottom:1px solid var(--line)}.metric span,label,small{color:var(--muted)}"
"label{display:block;margin:9px 0 5px}input,select{width:100%;border:1px solid var(--line);background:#091012;color:var(--ink);border-radius:9px;padding:10px;font:inherit}.row>*{flex:1}.message{min-height:22px;margin:10px 0 0;color:var(--muted)}"
"progress{width:100%;margin-top:10px;accent-color:var(--accent)}@media(max-width:850px){main{padding-top:20px}.layout{grid-template-columns:1fr}header{align-items:start;flex-direction:column}pre{height:48vh;min-height:280px}}"
"</style></head><body><main><header><div><h1>Klima WiFi</h1><p>ESP32-C6 · TD-YD-PSL MITM</p></div><div class='pill'><span id='dot' class='dot'></span><span id='connection'>Connecting…</span></div></header>"
"<div class='layout'><section class='panel'><div class='toolbar'><strong>Event stream</strong><span id='count' class='pill'>0 entries</span><button id='pause'>Pause</button><button id='clear'>Clear</button><button id='download'>Download</button></div><pre id='log' aria-live='polite'></pre></section>"
"<aside class='stack'><section class='panel'><h2>Air conditioner state</h2><div class='metric'><span>Profile</span><b id='profile'>—</b></div><div class='metric'><span>Panel / main link</span><b id='links'>—</b></div><div class='metric'><span>Power</span><b id='powerState'>—</b></div><div class='metric'><span>Temperature</span><b id='temperatureState'>—</b></div><div class='metric'><span>Mode / fan</span><b id='modeState'>—</b></div><div class='metric'><span>Quiet / units / timer</span><b id='featureState'>—</b></div><div class='metric'><span>Raw sensors</span><b id='sensors'>—</b></div></section>"
"<section class='panel'><h2>Wi-Fi control</h2><small id='controlHint'>Control requires the MITM profile and a healthy bidirectional link.</small><label for='token'>Device token</label><input id='token' type='password' autocomplete='off'><div class='row'><div><label for='mode'>Mode</label><select id='mode' class='control'><option value='cool'>Cooling</option><option value='fan'>Fan-only</option><option value='dry'>Dry</option></select></div><div><label for='fan'>Fan</label><select id='fan' class='control'><option value='low'>F1 / Low</option><option value='high'>F2 / High</option></select></div></div><label for='setpoint'>Target temperature 18–32°C</label><input id='setpoint' class='control' type='number' min='18' max='32' step='1' value='18'><div class='row'><div><label for='quiet'>Quiet mode</label><select id='quiet' class='control'><option value='false'>Disabled</option><option value='true'>Enabled</option></select></div><div><label for='units'>Display units</label><select id='units' class='control'><option value='false'>Celsius</option><option value='true'>Fahrenheit</option></select></div></div><small>Timer state is monitored. Remote timer control stays disabled until the duration field is decoded.</small><div class='row' style='margin-top:12px'><button class='control' data-power='true'>Turn on</button><button class='control' data-power='false'>Turn off</button><button id='apply' class='control'>Apply settings</button></div><p id='controlMessage' class='message' role='status'></p></section>"
"<section class='panel'><h2>Device</h2><div class='metric'><span>Firmware</span><b id='version'>—</b></div><div class='metric'><span>OTA partition</span><b id='partition'>—</b></div><div class='metric'><span>Wi-Fi STA</span><b id='ip'>—</b></div><div class='metric'><span>Translator OE</span><b id='oe'>—</b></div><div class='metric'><span>Free heap</span><b id='heap'>—</b></div></section>"
"<section class='panel'><h2>OTA update</h2><small>Select an application image built from this project. OTA uses the same device token as remote control.</small><label for='firmware'>Firmware image (.bin)</label><input id='firmware' type='file' accept='.bin,application/octet-stream'><button id='upload' style='margin-top:12px;width:100%'>Upload and restart</button><progress id='progress' value='0' max='100' hidden></progress><p id='otaMessage' class='message' role='status'></p></section></aside></div>"
"</main><script>"
"const $=s=>document.querySelector(s),logEl=$('#log'),lines=[];let after=0,paused=false,controlAvailable=false,controlsInitialized=false;"
"function addLine(x){lines.push(x);if(lines.length>3000)lines.shift();if(!paused){logEl.textContent=lines.join('\\n');logEl.scrollTop=logEl.scrollHeight}$('#count').textContent=lines.length+' entries'}"
"async function logs(){try{const r=await fetch('/api/logs?after='+after,{cache:'no-store'});if(!r.ok)throw Error(r.status);const d=await r.json();for(const e of d.entries){after=e.seq;addLine(String(e.seq).padStart(6,'0')+'  '+e.text)}$('#dot').className='dot ok';$('#connection').textContent='online'}catch(e){$('#dot').className='dot';$('#connection').textContent='disconnected'}finally{setTimeout(logs,500)}}"
"async function status(){try{const d=await(await fetch('/api/status',{cache:'no-store'})).json();$('#version').textContent=d.version;$('#partition').textContent=d.ota_partition;$('#ip').textContent=d.sta_connected?d.sta_ip:'disconnected';$('#oe').textContent=d.preflight&&d.preflight.oe_enabled?'enabled':'disabled';$('#heap').textContent=Math.round(d.free_heap/1024)+' KiB'}catch(e){}setTimeout(status,2500)}"
"async function acState(){try{const d=await(await fetch('/api/ac-state',{cache:'no-store'})).json();controlAvailable=d.control.available;$('#profile').textContent=d.profile;$('#links').textContent=(d.link.panel?'OK':'missing')+' / '+(d.link.main?'OK':'missing');$('#powerState').textContent=d.state.power?'on':'off';const validSetpoint=d.state.setpoint_c>=18&&d.state.setpoint_c<=32;$('#temperatureState').textContent=d.state.power&&validSetpoint?d.state.setpoint_c+'°C':'—';$('#modeState').textContent=d.state.power?d.state.mode+' / '+d.state.fan+' ('+d.state.mode_fan_code+')':'— (raw '+d.state.mode_fan_code+')';$('#featureState').textContent=(d.state.quiet?'quiet':'normal')+' / '+(d.state.units_fahrenheit?'°F':'°C')+' / '+(d.state.timer?'timer ON':'timer OFF');if(!controlsInitialized){if(['cool','fan','dry'].includes(d.state.mode))$('#mode').value=d.state.mode;if(['low','high'].includes(d.state.fan))$('#fan').value=d.state.fan;if(validSetpoint)$('#setpoint').value=d.state.setpoint_c;$('#quiet').value=String(d.state.quiet);$('#units').value=String(d.state.units_fahrenheit);controlsInitialized=true}$('#sensors').textContent=d.state.sensor_1_raw+' / '+d.state.sensor_2_raw;document.querySelectorAll('.control').forEach(x=>x.disabled=!controlAvailable);$('#controlHint').textContent=controlAvailable?'The MITM bridge and both links are active. State changes wait for confirmation from the main controller.':'Control unavailable: fresh frames are required from both directions.'}catch(e){}setTimeout(acState,1000)}"
"async function command(body){const token=$('#token').value;if(!token){$('#controlMessage').textContent='Enter the device token.';return}try{const r=await fetch('/api/control',{method:'POST',headers:{'Content-Type':'application/json','X-Klima-Token':token},body:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw Error(d.error||r.status);$('#controlMessage').textContent='Command accepted. Sequence '+d.sequence+'.'}catch(e){$('#controlMessage').textContent='Error: '+e.message}}"
"document.querySelectorAll('[data-power]').forEach(b=>b.onclick=()=>command({power:b.dataset.power==='true'}));$('#apply').onclick=()=>command({mode:$('#mode').value,fan:$('#fan').value,setpoint_c:Number($('#setpoint').value),quiet:$('#quiet').value==='true',units_fahrenheit:$('#units').value==='true'});"
"$('#pause').onclick=()=>{paused=!paused;$('#pause').textContent=paused?'Resume':'Pause';if(!paused){logEl.textContent=lines.join('\\n');logEl.scrollTop=logEl.scrollHeight}};$('#clear').onclick=()=>{lines.length=0;logEl.textContent='';$('#count').textContent='0 entries'};"
"$('#download').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([lines.join('\\n')+'\\n'],{type:'text/plain'}));a.download='klima-wifi-'+new Date().toISOString().replaceAll(':','-')+'.log';a.click();URL.revokeObjectURL(a.href)};"
"$('#upload').onclick=()=>{const f=$('#firmware').files[0],token=$('#token').value;if(!f||!token){$('#otaMessage').textContent='Select a firmware image and enter the device token.';return}const x=new XMLHttpRequest();x.open('POST','/api/ota');x.setRequestHeader('X-Klima-Token',token);x.upload.onprogress=e=>{if(e.lengthComputable){$('#progress').hidden=false;$('#progress').value=e.loaded/e.total*100}};x.onload=()=>{$('#otaMessage').textContent=x.status===200?'Update accepted. The device is restarting.':'OTA error: '+x.responseText};x.onerror=()=>$('#otaMessage').textContent='Connection interrupted.';x.send(f)};"
"logs();status();acState();</script></body></html>";
